package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.*;import android.content.*;import android.media.*;import android.net.*;import android.os.*;import android.telephony.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Foreground owner of one authenticated local FM session; no automatic start at boot. */
public final class FmService extends Service implements AudioManager.OnAudioFocusChangeListener {
    static final String CHANGED="ro.leo.visual.FM_CHANGED";static volatile FmService instance;static volatile boolean playing,starting,scanning,seeking,speaker;static final TreeMap<Integer,Integer> stations=new TreeMap<Integer,Integer>();static volatile int frequency=101300,signal=-128,volume=8;static volatile String state=L.t("Oprit"),stationName="",radioText="";
    private final Handler main=new Handler();private final ExecutorService control=Executors.newSingleThreadExecutor();private volatile LocalSocket socket;private volatile BufferedWriter writer;private volatile boolean closed;private AudioManager audio;
    private final ArrayList<TelephonyManager> phones=new ArrayList<TelephonyManager>();private final ArrayList<PhoneStateListener> listeners=new ArrayList<PhoneStateListener>();
    private final AudioDeviceCallback devices=new AudioDeviceCallback(){public void onAudioDevicesRemoved(AudioDeviceInfo[] removed){if(!wired(FmService.this))stop(L.t("Oprit · căști deconectate"));}};
    private final Runnable heartbeat=new Runnable(){public void run(){if(closed)return;control.execute(new Runnable(){public void run(){send("P");}});main.postDelayed(this,3000);}};
    static boolean wired(Context c){AudioManager a=(AudioManager)c.getSystemService(AUDIO_SERVICE);for(AudioDeviceInfo d:a.getDevices(AudioManager.GET_DEVICES_OUTPUTS))if(d.getType()==AudioDeviceInfo.TYPE_WIRED_HEADSET||d.getType()==AudioDeviceInfo.TYPE_WIRED_HEADPHONES)return true;return false;}
    public IBinder onBind(Intent i){return null;}
    public void onCreate(){super.onCreate();instance=this;audio=(AudioManager)getSystemService(AUDIO_SERVICE);loadStations(this);speaker=false;stationName="";radioText="";frequency=getSharedPreferences("fm",0).getInt("frequency",101300);volume=Math.max(0,Math.min(100,getSharedPreferences("fm",0).getInt("volume",8)));audio.registerAudioDeviceCallback(devices,main);}
    private void monitorCalls(){TelephonyManager base=(TelephonyManager)getSystemService(TELEPHONY_SERVICE);phones.add(base);SubscriptionManager subscriptions=(SubscriptionManager)getSystemService(TELEPHONY_SUBSCRIPTION_SERVICE);List<SubscriptionInfo> active=subscriptions.getActiveSubscriptionInfoList();if(active!=null)for(SubscriptionInfo info:active)phones.add(base.createForSubscriptionId(info.getSubscriptionId()));for(TelephonyManager phone:phones){if(phone.getCallState()!=TelephonyManager.CALL_STATE_IDLE)throw new IllegalStateException(L.t("Apel în curs"));PhoneStateListener listener=new PhoneStateListener(){public void onCallStateChanged(int value,String ignored){if(value!=TelephonyManager.CALL_STATE_IDLE)stop(L.t("Oprit · apel"));}};listeners.add(listener);phone.listen(listener,PhoneStateListener.LISTEN_CALL_STATE);}}
    public int onStartCommand(Intent i,int flags,int id){if(i==null||"stop".equals(i.getAction())){stop(L.t("Oprit"));return START_NOT_STICKY;}if(playing||starting)return START_NOT_STICKY;if(!wired(this)){stop(L.t("Conectează căștile cu fir"));return START_NOT_STICKY;}try{monitorCalls();}catch(RuntimeException denied){stop(L.t("FM indisponibil în timpul apelului sau fără acces la starea lui"));return START_NOT_STICKY;}if(audio.requestAudioFocus(this,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){stop(L.t("Sunet ocupat"));return START_NOT_STICKY;}
        starting=true;state=L.t("Se pornește radioul…");NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);NotificationChannel channel=new NotificationChannel("leo-fm",L.t("Radio FM Leo"),NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);nm.createNotificationChannel(channel);startForeground(426,notification());publish();
        control.execute(new Runnable(){public void run(){connect();}});main.postDelayed(heartbeat,3000);main.postDelayed(new Runnable(){public void run(){if(starting&&!closed)stop(L.t("FM nu a răspuns la pornire"));}},20000);return START_NOT_STICKY;}
    private Notification notification(){PendingIntent open=PendingIntent.getActivity(this,426,new Intent(this,FmActivity.class),PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent stop=PendingIntent.getService(this,427,new Intent(this,FmService.class).setAction("stop"),PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"leo-fm").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Radio FM · "+String.format(Locale.ROOT,"%.1f MHz",frequency/1000f)).setContentText(state).setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,L.t("Oprește"),stop).build()).build();}
    private void publish(){sendBroadcast(new Intent(CHANGED).setPackage(getPackageName()));if(!closed&&(starting||playing))((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(426,notification());}
    private void connect(){try{java.lang.Process launch=new ProcessBuilder("/system/bin/leo-su","-c","/data/leo-fm/trial --session </dev/null >/data/leo-fm/launch.log 2>&1 &").start();if(!launch.waitFor(3,TimeUnit.SECONDS)){launch.destroy();throw new IOException();}if(launch.exitValue()!=0)throw new IOException();LocalSocket linked=null;for(int n=0;n<80&&!closed;n++){LocalSocket candidate=new LocalSocket();try{candidate.connect(new LocalSocketAddress("leo.fm.session.v1",LocalSocketAddress.Namespace.ABSTRACT));linked=candidate;break;}catch(IOException absent){candidate.close();SystemClock.sleep(100);}}if(linked==null)throw new IOException();if(linked.getPeerCredentials().getUid()!=0){linked.close();throw new IOException();}if(closed){linked.close();return;}socket=linked;writer=new BufferedWriter(new OutputStreamWriter(linked.getOutputStream(),"UTF-8"));send("T"+frequency);final LocalSocket reading=linked;new Thread(new Runnable(){public void run(){read(reading);}},"LeoFMReader").start();}catch(Exception failure){main.post(new Runnable(){public void run(){stop(L.t("Pachetul FM sau conexiunea root este indisponibilă"));}});}}
    private void read(LocalSocket linked){try{BufferedReader reader=new BufferedReader(new InputStreamReader(linked.getInputStream(),"UTF-8"));String line;while((line=reader.readLine())!=null&&!closed){String[] fields=line.split(" ");if(fields.length==3&&(fields[0].equals("PS")||fields[0].equals("RT"))){final boolean ps=fields[0].equals("PS");final int khz=Integer.parseInt(fields[1]);final String value=decodeRds(fields[2],ps?8:64);main.post(new Runnable(){public void run(){if(closed||khz!=frequency||scanning||seeking)return;if(ps)stationName=value;else radioText=value;publish();}});
        }else if(fields.length==4&&fields[0].equals("SEEKDONE")){final int khz=Integer.parseInt(fields[1]),rssi=Integer.parseInt(fields[2]);final boolean found=fields[3].equals("1");if(khz<87500||khz>108000||rssi<-128||rssi>127)throw new IOException();main.post(new Runnable(){public void run(){if(closed)return;seeking=false;frequency=khz;signal=rssi;stationName="";radioText="";state=found?(speaker?L.t("În redare · difuzor"):L.t("În redare · căști")):L.t("Niciun alt post găsit");getSharedPreferences("fm",0).edit().putInt("frequency",frequency).apply();setVolume(volume);publish();}});
        }else if(line.equals("SEEKING")){main.post(new Runnable(){public void run(){if(!closed){seeking=true;state=L.t("Se caută un post…");publish();}}});
        }else if(fields.length==3&&(fields[0].equals("READY")||fields[0].equals("STATUS")||fields[0].equals("DONE"))){final boolean done=fields[0].equals("DONE");final int khz=Integer.parseInt(fields[1]),rssi=Integer.parseInt(fields[2]);if(khz<87500||khz>108000||rssi<-128||rssi>127)throw new IOException();main.post(new Runnable(){public void run(){if(closed)return;starting=false;playing=true;if(done){scanning=false;saveStations();}if(khz==frequency){signal=rssi;state=speaker?L.t("În redare · difuzor"):L.t("În redare · căști");getSharedPreferences("fm",0).edit().putInt("frequency",frequency).apply();}setVolume(volume);publish();}});}else if(fields.length==3&&fields[0].equals("FOUND")){final int khz=Integer.parseInt(fields[1]),rssi=Integer.parseInt(fields[2]);if(khz>=87500&&khz<=108000&&rssi>=-128&&rssi<=127)main.post(new Runnable(){public void run(){if(closed)return;for(Iterator<Map.Entry<Integer,Integer>> it=stations.entrySet().iterator();it.hasNext();){Map.Entry<Integer,Integer> entry=it.next();if(Math.abs(entry.getKey()-khz)<=200){if(entry.getValue()>=rssi)return;it.remove();}}if(stations.size()<50)stations.put(khz,rssi);publish();}});
        }else if(fields.length==2&&fields[0].equals("PROGRESS")){final int khz=Integer.parseInt(fields[1]);main.post(new Runnable(){public void run(){if(!closed){state=String.format(Locale.ROOT,L.t("Scanare · %.1f MHz"),khz/1000f);publish();}}});
        }else if(line.equals("SCANNING")){main.post(new Runnable(){public void run(){if(!closed){scanning=true;publish();}}});
        }else if(line.startsWith("ERROR"))main.post(new Runnable(){public void run(){if(!closed){state=L.t("Acordare nereușită");publish();}}});}}catch(Exception ignored){}finally{main.post(new Runnable(){public void run(){if(!closed)stop(L.t("Sesiune FM închisă"));}});}}
    static String decodeRds(String hex,int limit)throws IOException {if(hex.length()%2!=0||hex.length()>limit*2)throw new IOException();StringBuilder value=new StringBuilder();for(int i=0;i<hex.length();i+=2){int a=Character.digit(hex.charAt(i),16),b=Character.digit(hex.charAt(i+1),16);if(a<0||b<0)throw new IOException();int c=(a<<4)|b;if(c==0||c==13)break;value.append(c>=32&&c<=126?(char)c:c>=128?'�':' ');}return value.toString().trim();}
    private void send(String command){if(closed)return;try{BufferedWriter out=writer;if(out==null)return;synchronized(out){out.write(command);out.write('\n');out.flush();}}catch(IOException failure){main.post(new Runnable(){public void run(){stop(L.t("Conexiune FM închisă"));}});}}
    void tune(final int khz){if(scanning||seeking)return;if(khz<87500||khz>108000||khz%100!=0)return;frequency=khz;stationName="";radioText="";if(playing){state=L.t("Se acordează…");control.execute(new Runnable(){public void run(){send("T"+khz);}});}else getSharedPreferences("fm",0).edit().putInt("frequency",khz).apply();publish();}
    void setVolume(int value){
        volume=Math.max(0,Math.min(100,value));
        getSharedPreferences("fm",0).edit().putInt("volume",volume).apply();
        if(playing&&!closed){final int requested=volume;control.execute(new Runnable(){public void run(){
            try{int result=(Integer)Class.forName("android.media.AudioSystem").getMethod("setParameters",String.class).invoke(null,String.format(Locale.ROOT,"fm_volume=%.2f",requested/100f));if(result!=0)throw new IOException();}
            catch(Exception failure){main.post(new Runnable(){public void run(){stop(L.t("Controlul volumului FM nu este disponibil"));}});}
        }});}
        publish();
    }
    static void loadStations(Context c){if(playing||starting)return;stations.clear();for(String part:c.getSharedPreferences("fm",0).getString("stations","").split(","))try{String[] pair=part.split(":");int khz=Integer.parseInt(pair[0]),rssi=Integer.parseInt(pair[1]);if(khz>=87500&&khz<=108000&&rssi>=-128&&rssi<=127)stations.put(khz,rssi);}catch(RuntimeException ignored){}}
    private void saveStations(){StringBuilder values=new StringBuilder();for(Map.Entry<Integer,Integer> entry:stations.entrySet()){if(values.length()>0)values.append(',');values.append(entry.getKey()).append(':').append(entry.getValue());}getSharedPreferences("fm",0).edit().putString("stations",values.toString()).apply();}
    void seek(final boolean upward){if(!playing||scanning||seeking)return;seeking=true;stationName="";radioText="";state=L.t("Se caută un post…");publish();control.execute(new Runnable(){public void run(){send(upward?"U":"D");}});}
    void scan(){if(!playing||scanning||seeking)return;stationName="";radioText="";stations.clear();scanning=true;state=L.t("Se scanează banda…");publish();control.execute(new Runnable(){public void run(){send("S");}});}
    void setSpeaker(final boolean enabled){
        if(!playing||closed)return;
        control.execute(new Runnable(){public void run(){
            try{
                java.lang.Process route=new ProcessBuilder("/system/bin/leo-su","-c","/data/leo-fm/route "+(enabled?"2":"4")).start();
                if(!route.waitFor(3,TimeUnit.SECONDS)){route.destroy();throw new IOException();}
                if(route.exitValue()!=0)throw new IOException();
                main.post(new Runnable(){public void run(){if(!closed){speaker=enabled;state=enabled?L.t("În redare · difuzor"):L.t("În redare · căști");publish();}}});
            }catch(Exception failed){
                main.post(new Runnable(){public void run(){if(!closed){state=L.t("Ruta audio nu a putut fi schimbată");publish();}}});
            }
        }});
    }
    private void stop(String reason){if(closed)return;android.util.Log.i("LeoFM","Stop: "+reason);state=reason;playing=false;starting=false;scanning=false;seeking=false;stationName="";radioText="";publish();stopSelf();}
    public void onAudioFocusChange(int focus){if(focus<0)stop(L.t("Oprit · alt sunet"));}
    public void onDestroy(){closed=true;main.removeCallbacksAndMessages(null);LocalSocket linked=socket;if(linked!=null){try{linked.shutdownOutput();}catch(IOException ignored){}try{linked.shutdownInput();}catch(IOException ignored){}try{linked.close();}catch(IOException ignored){}}control.shutdownNow();for(int n=0;n<listeners.size();n++)try{phones.get(n).listen(listeners.get(n),PhoneStateListener.LISTEN_NONE);}catch(RuntimeException ignored){}audio.unregisterAudioDeviceCallback(devices);audio.abandonAudioFocus(this);playing=false;starting=false;scanning=false;seeking=false;speaker=false;stationName="";radioText="";instance=null;stopForeground(true);sendBroadcast(new Intent(CHANGED).setPackage(getPackageName()));super.onDestroy();}
}
